fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // tol is strictly positive by assumption
    // We check if the difference (a - b) is strictly between -tol and +tol.
    // Equivalently, absolute difference < tol.
    let diff = a.wrapping_sub(b);
    // Convert i8 to i16 to avoid overflow issues when taking absolute value
    // or just take absolute with careful casting:
    (diff > -tol) && (diff < tol)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions: 
    // - len(a) == len(b) > 0
    // - tol > 0

    // Map element-wise using is_close_i8 to produce the boolean vector.
    // Since lengths are equal and > 0, zip is safe here.

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}